.darma-loader-darma-b14-hammock-sway { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #78350f); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .7); position: relative; }
.darma-loader-darma-b14-hammock-sway::before, .darma-loader-darma-b14-hammock-sway::after { content: ''; position: absolute; bottom: 0; width: 6%; height: 78%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 24%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b14-hammock-sway::before { left: 4%; }
.darma-loader-darma-b14-hammock-sway::after { right: 4%; }
.darma-loader-darma-b14-hammock-sway .darma-loader-darma-b14-hammock-sway__net { position: absolute; top: 24%; left: 10%; width: 80%; height: 34%; border-top: calc(var(--loader-size, 120px) * .022) solid var(--accent); border-radius: 0 0 50% 50% / 0 0 100% 100%; transform-origin: top center; background: repeating-linear-gradient(90deg, var(--accent) 0 5%, transparent 5% 11%); animation: darma-loader-darma-b14-hammock-sway-hammock calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-hammock-sway-hammock { 0%, 100% { transform: rotate(-7deg); } 50% { transform: rotate(7deg); } }

